import decimal as _decimal


def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {
        "inland": _decimal.Decimal("4.20"),
        "coastal": _decimal.Decimal("5.75"),
        "highland": _decimal.Decimal("9.10"),
    }

    try:
        base_rate = rates[zone]
    except (KeyError, TypeError):
        raise ValueError("invalid zone") from None

    try:
        weight = _decimal.Decimal(str(weight_kg))
    except (_decimal.InvalidOperation, ValueError):
        raise ValueError("weight_kg must be greater than 0") from None

    if not weight.is_finite() or weight <= 0:
        raise ValueError("weight_kg must be greater than 0")

    first_tier = min(weight, _decimal.Decimal("10"))
    second_tier = min(
        max(weight - _decimal.Decimal("10"), _decimal.Decimal("0")),
        _decimal.Decimal("40"),
    )
    third_tier = max(weight - _decimal.Decimal("50"), _decimal.Decimal("0"))

    subtotal = (
        first_tier * base_rate
        + second_tier * _decimal.Decimal("0.60") * base_rate
        + third_tier * _decimal.Decimal("0.35") * base_rate
    ).quantize(_decimal.Decimal("0.01"), rounding=_decimal.ROUND_HALF_UP)

    if subtotal % _decimal.Decimal("1.00") == 0:
        subtotal -= _decimal.Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += _decimal.Decimal("18.50")

    return float(
        subtotal.quantize(
            _decimal.Decimal("0.01"),
            rounding=_decimal.ROUND_HALF_UP,
        )
    )

